// Simple application — hardened for security best practices
'use strict';

const express = require('express');
const helmet = require('helmet');         // Security headers
const rateLimit = require('express-rate-limit'); // Rate limiting

const app = express();

// ─── Middleware ────────────────────────────────────────────────────────────────

// 1. Parse JSON bodies with a size limit to prevent payload attacks
app.use(express.json({ limit: '10kb' }));

// 2. Set secure HTTP headers and remove X-Powered-By
app.use(helmet());

// 3. Apply rate limiting to all requests
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                  // Limit each IP to 100 requests per window
  standardHeaders: true,     // Return rate limit info in RateLimit-* headers
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// ─── Routes ───────────────────────────────────────────────────────────────────

// Health check — no sensitive data exposed
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users list — validate query params, sanitize output
app.get('/users', (req, res, next) => {
  try {
    // Input validation: reject unexpected query parameters
    const allowedParams = new Set(['page', 'limit']);
    const receivedParams = Object.keys(req.query);
    const invalidParams = receivedParams.filter((p) => !allowedParams.has(p));

    if (invalidParams.length > 0) {
      return res.status(400).json({
        error: `Unexpected query parameter(s): ${invalidParams.join(', ')}`,
      });
    }

    // Input validation: page and limit must be positive integers
    const page = parseInt(req.query.page, 10) || 1;
    const limit = parseInt(req.query.limit, 10) || 10;

    if (page < 1 || limit < 1 || limit > 100) {
      return res.status(400).json({
        error: 'Invalid pagination values. page >= 1, 1 <= limit <= 100.',
      });
    }

    // NOTE: In production, replace with a real database query.
    // Never return raw DB rows — explicitly select only the fields you need.
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Sanitize output: only return fields clients are permitted to see
    const safeUsers = allUsers.map(({ id, name }) => ({ id, name }));

    const start = (page - 1) * limit;
    const paginated = safeUsers.slice(start, start + limit);

    res.json({ page, limit, total: safeUsers.length, data: paginated });
  } catch (err) {
    next(err); // Forward unexpected errors to the global error handler
  }
});

// ─── 404 Handler ──────────────────────────────────────────────────────────────

// Catch all unmatched routes before they reach the error handler
app.use((req, res) => {
  res.status(404).json({ error: 'Resource not found.' });
});

// ─── Global Error Handler ─────────────────────────────────────────────────────

// Must have 4 parameters for Express to recognise it as an error handler
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Log the full error internally for debugging/auditing
  console.error({
    message: err.message,
    stack: err.stack,
    url: req.originalUrl,
    method: req.method,
    timestamp: new Date().toISOString(),
  });

  // Never leak stack traces or internal details to the client
  const status = err.status || err.statusCode || 500;
  res.status(status).json({
    error: status < 500 ? err.message : 'An internal server error occurred.',
  });
});

// ─── Exports ──────────────────────────────────────────────────────────────────

// Export app without starting the server — start it in a separate entry point
// (e.g. server.js) so test suites can import the app cleanly.
module.exports = app;

// server.js — Entry point. Kept separate from app.js so tests can import
// the Express app without side-effects (i.e. without binding to a port).
'use strict';

const app = require('./app');

const PORT = parseInt(process.env.PORT, 10) || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

