// Simple application with security best practices applied
// Improvements: security headers, rate limiting, error handling,
// input validation, 404 handling, and environment-based config.

'use strict';

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();
const PORT = process.env.PORT || 3000;

// ---------------------------------------------------------------------------
// 1. SECURITY HEADERS
//    helmet() sets a suite of HTTP headers that protect against well-known
//    web vulnerabilities (XSS, clickjacking, MIME sniffing, etc.).
// ---------------------------------------------------------------------------
app.use(helmet());

// ---------------------------------------------------------------------------
// 2. BODY PARSING (with size limit)
//    Limiting the request body size prevents large-payload DoS attacks.
// ---------------------------------------------------------------------------
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ---------------------------------------------------------------------------
// 3. RATE LIMITING
//    Restrict each IP to 100 requests per 15-minute window to mitigate
//    brute-force and denial-of-service attacks.
// ---------------------------------------------------------------------------
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  standardHeaders: true,  // Return rate-limit info in RateLimit-* headers
  legacyHeaders: false,   // Disable X-RateLimit-* headers
  message: { error: 'Too many requests. Please try again later.' },
});
app.use(limiter);

// ---------------------------------------------------------------------------
// 4. ROUTES
// ---------------------------------------------------------------------------

// Health check — lightweight, no sensitive data
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users list — validate query params before use
app.get('/users', (req, res, next) => {
  try {
    const { page = '1', limit = '10' } = req.query;

    // Input validation: ensure pagination params are positive integers
    const parsedPage = parseInt(page, 10);
    const parsedLimit = parseInt(limit, 10);

    if (
      isNaN(parsedPage) || parsedPage < 1 ||
      isNaN(parsedLimit) || parsedLimit < 1 || parsedLimit > 100
    ) {
      return res.status(400).json({
        error: 'Invalid pagination parameters. "page" and "limit" must be positive integers. "limit" max is 100.',
      });
    }

    // NOTE: In a real app, replace this with a database query using
    // parameterised queries or an ORM to prevent SQL injection.
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    res.json({ page: parsedPage, limit: parsedLimit, total: users.length, data: users });
  } catch (err) {
    next(err); // Forward unexpected errors to the global error handler
  }
});

// ---------------------------------------------------------------------------
// 5. 404 HANDLER
//    Catches requests to any undefined route and returns a clean JSON
