'use strict';

/**
 * app.js — Express application with security best practices applied.
 *
 * Key improvements over the original:
 *  - Helmet for secure HTTP headers
 *  - Rate limiting on all routes
 *  - Strict input validation via a reusable helper
 *  - Centralized error handler (no raw stack traces to clients)
 *  - Body-size cap on JSON payloads
 *  - Explicit CORS policy
 *  - Port sourced from environment variable
 *  - Least-privilege data responses (emails stripped from list view)
 */

const express = require('express');
const helmet  = require('helmet');             // Secure HTTP headers
const rateLimit = require('express-rate-limit'); // Rate limiting
const cors    = require('cors');               // CORS policy

const app = express();

// ---------------------------------------------------------------------------
// 1. Security headers (removes X-Powered-By, sets CSP, HSTS, etc.)
// ---------------------------------------------------------------------------
app.use(helmet());

// ---------------------------------------------------------------------------
// 2. CORS — explicitly allow only known origins.
//    Replace ALLOWED_ORIGIN with your real front-end URL.
// ---------------------------------------------------------------------------
const ALLOWED_ORIGINS = (process.env.ALLOWED_ORIGINS || '')
  .split(',')
  .map(o => o.trim())
  .filter(Boolean);

app.use(cors({
  origin: (origin, callback) => {
    // Allow server-to-server requests (no Origin header) only in non-production.
    if (!origin && process.env.NODE_ENV !== 'production') {
      return callback(null, true);
    }
    if (ALLOWED_ORIGINS.includes(origin)) {
      return callback(null, true);
    }
    callback(new Error(`CORS: origin '${origin}' is not allowed`));
  },
  methods: ['GET', 'POST'],
  allowedHeaders: ['Content-Type', 'Authorization'],
}));

// ---------------------------------------------------------------------------
// 3. Body parsing with a hard size cap (prevents large-payload attacks)
// ---------------------------------------------------------------------------
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// ---------------------------------------------------------------------------
// 4. Rate limiting — max 100 requests per 15 minutes per IP across all routes
