const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();
const PORT = process.env.PORT || 3000;

// -------------------------------------------------------------------
// 1. SECURITY HEADERS
//    helmet() sets a suite of protective HTTP headers, including:
//    - Content-Security-Policy
//    - X-Content-Type-Options (prevents MIME sniffing)
//    - X-Frame-Options (prevents clickjacking)
//    - Strict-Transport-Security (enforces HTTPS)
// -------------------------------------------------------------------
app.use(helmet());

// -------------------------------------------------------------------
// 2. RATE LIMITING
//    Limits each IP to 100 requests per 15-minute window.
//    Protects against DoS attacks and brute-force attempts.
// -------------------------------------------------------------------
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  standardHeaders: true,  // Return rate-limit info in `RateLimit-*` headers
  legacyHeaders: false,   // Disable the `X-RateLimit-*` headers
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// -------------------------------------------------------------------
// 3. REQUEST BODY PARSING
//    Parses incoming JSON payloads and enforces a size limit to
//    prevent large payload attacks.
// -------------------------------------------------------------------
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// -------------------------------------------------------------------
// ROUTES
// -------------------------------------------------------------------

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  // Input validation: reject unexpected query parameters
  const allowedParams = ['id', 'name'];
  const receivedParams = Object.keys(req.query);
  const invalidParams = receivedParams.filter(p => !allowedParams.includes(p));

  if (invalidParams.length > 0) {
    return res.status(400).json({
      error: `Invalid query parameter(s): ${invalidParams.join(', ')}`,
    });
  }

  // Validate 'id' param is a safe positive integer if provided
  if (req.query.id !== undefined) {
    const id = Number(req.query.id);
    if (!Number.isInteger(id) || id <= 0) {
      return res.status(400).json({ error: 'Parameter "id" must be a positive integer.' });
    }
  }

  // NOTE: In production, replace this with a real database query.
  //       Avoid exposing sensitive fields (e.g., passwords, tokens).
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  res.json(users);
});

// -------------------------------------------------------------------
// 4. 404 HANDLER
//    Catches requests to undefined routes and returns a structured
//    error instead of Express's default HTML response (which can
//    leak framework/version information).
// -------------------------------------------------------------------
app.use((req, res) => {
  res.status(404).json({ error: 'Route not found.' });
});

// -------------------------------------------------------------------
// 5. CENTRALIZED ERROR HANDLING MIDDLEWARE
//    Catches errors passed via next(err) from any route or middleware.
//    - Logs the full error server-side for debugging.
//    - Returns a sanitized message to the client to avoid leaking
//      stack traces or internal implementation details.
// -------------------------------------------------------------------
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  console.error(`[Error] ${req.method} ${req.path} —`, err);

  const statusCode = err.status || err.statusCode || 500;

  // Never expose stack traces or raw error messages in production
  const message =
    process.env.NODE_ENV === 'production'
      ? 'An internal server error occurred.'
      : err.message;

  res.status(statusCode).json({ error: message });
});

// -------------------------------------------------------------------
// SERVER STARTUP
// -------------------------------------------------------------------
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

