'use strict';

// ------------------------------------------------------------
// Dependencies
// npm install express helmet express-rate-limit
// ------------------------------------------------------------
const express = require('express');
const helmet  = require('helmet');
const rateLimit = require('express-rate-limit');

const app  = express();
const PORT = process.env.PORT || 3000;

// ------------------------------------------------------------
// 1. Security Headers (helmet sets ~14 protective HTTP headers)
// ------------------------------------------------------------
app.use(helmet());

// ------------------------------------------------------------
// 2. Body Parsing — enforce a size limit to prevent payload floods
// ------------------------------------------------------------
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// ------------------------------------------------------------
// 3. Rate Limiting — prevent brute-force / DoS
// ------------------------------------------------------------
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                  // max requests per window per IP
  standardHeaders: true,     // return rate-limit info in RateLimit-* headers
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// ------------------------------------------------------------
// Routes
// ------------------------------------------------------------

// Health check — no sensitive data, safe to leave public
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users listing — validate query params; omit sensitive fields
app.get('/users', (req, res, next) => {
  try {
    // Example: validate an optional ?limit= query parameter
    const MAX_LIMIT = 100;
    let limit = MAX_LIMIT;

    if (req.query.limit !== undefined) {
      limit = parseInt(req.query.limit, 10);

      if (Number.isNaN(limit) || limit < 1 || limit > MAX_LIMIT) {
        return res.status(400).json({
          error: `'limit' must be an integer between 1 and ${MAX_LIMIT}.`,
        });
      }
    }

    // TODO: replace with a real database query (parameterised — never interpolate user
    //       input directly into a query string).
    const allUsers = [
      { id: 1, name: 'Alice' }, // email intentionally omitted — return only what callers need
      { id: 2, name: 'Bob'   },
    ];

    return res.json(allUsers.slice(0, limit));
  } catch (err) {
    // Forward unexpected errors to the global error handler
    return next(err);
  }
});

// ------------------------------------------------------------
// 4. 404 Handler — catch unmatched routes before the error handler
// ------------------------------------------------------------
app.use((req, res) => {
  res.status(404).json({ error: 'Resource not found.' });
});

// ------------------------------------------------------------
// 5. Global Error Handler
//    Must have exactly four parameters so Express recognises it as an
//    error-handling middleware. Never expose stack traces in production.
// ------------------------------------------------------------
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  const isDev = process.env.NODE_ENV === 'development';

  // Log the full error server-side (swap console.error for a proper logger in production)
  console.error('[Error]', err);

  res.status(err.status || 500).json({
    error:   err.message || 'Internal server error.',
    // Expose stack trace only in development — never in production
    ...(isDev && { stack: err.stack }),
  });
});

// ------------------------------------------------------------
// Start server only when this module is run directly, not when
// it is required by tests (prevents port conflicts in test suites)
// ------------------------------------------------------------
if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT} [${process.env.NODE_ENV || 'development'}]`);
  });
}

module.exports = app;

