// app.js — Express application with security best practices applied

'use strict';

const express = require('express');
const helmet  = require('helmet');
const cors    = require('cors');
const rateLimit = require('express-rate-limit');

const app  = express();
const PORT = parseInt(process.env.PORT, 10) || 3000;

// ---------------------------------------------------------------------------
// 1. Security headers (helmet sets X-Content-Type-Options, X-Frame-Options,
//    Strict-Transport-Security, and more in one call)
// ---------------------------------------------------------------------------
app.use(helmet());

// ---------------------------------------------------------------------------
// 2. CORS — restrict to known origins; adjust ALLOWED_ORIGIN in your env
// ---------------------------------------------------------------------------
const ALLOWED_ORIGIN = process.env.ALLOWED_ORIGIN || 'http://localhost:3000';
app.use(cors({
  origin: (origin, callback) => {
    // Allow server-to-server requests (no Origin header) and the allowed origin
    if (!origin || origin === ALLOWED_ORIGIN) {
      callback(null, true);
    } else {
      callback(new Error(`CORS: origin '${origin}' not allowed`));
    }
  },
  methods: ['GET'],           // only expose the methods this API actually uses
  allowedHeaders: ['Content-Type', 'Authorization'],
}));

// ---------------------------------------------------------------------------
// 3. Body parsing with a payload size cap to prevent large-payload DoS
// ---------------------------------------------------------------------------
app.use(express.json({ limit: '10kb' }));

// ---------------------------------------------------------------------------
// 4. Rate limiting — 100 requests per 15-minute window per IP
// ---------------------------------------------------------------------------
const limiter = rateLimit({
  windowMs : 15 * 60 * 1000, // 15 minutes
  max      : 100,
  standardHeaders: true,      // return RateLimit-* headers
  legacyHeaders  : false,
  message  : { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// ---------------------------------------------------------------------------
// 5. Routes
// ---------------------------------------------------------------------------

// Health check — no sensitive data, safe to expose publicly
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users — validate and sanitise any query parameters before use
app.get('/users', (req, res, next) => {
  try {
    // Example: optional ?limit= query param with strict validation
    const rawLimit = req.query.limit;
    if (rawLimit !== undefined) {
      const limit = parseInt(rawLimit, 10);
      if (isNaN(limit) || limit < 1 || limit > 100) {
        // Use a plain object — never reflect raw user input back in errors
        return res.status(400).json({
          error: "'limit' must be an integer between 1 and 100.",
        });
      }
    }

    // In a real app this data would come from a parameterised DB query,
    // not a hard-coded array.
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob',   email: 'bob@example.com'   },
    ];

    res.json(users);
  } catch (err) {
    // Forward unexpected errors to the central error handler
    next(err);
  }
});

// ---------------------------------------------------------------------------
// 6. 404 handler — must be placed after all valid routes
// ---------------------------------------------------------------------------
app.use((req, res) => {
  res.status(404).json({ error: 'Resource not found.' });
});

// ---------------------------------------------------------------------------
// 7. Central error handler (4-argument signature is required by Express)
//    — never leaks stack traces or internal details to the client
// ---------------------------------------------------------------------------
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Log full error internally (replace with a proper logger in production)
  console.error('[error]', err);

  // CORS errors get a specific status code
  if (err.message && err.message.startsWith('CORS:')) {
    return res.status(403).json({ error: 'Forbidden: CORS policy violation.' });
  }

  // Generic safe response — no internal detail exposed
  const status = err.status || err.statusCode || 500;
  res.status(status).json({
    error: status < 500 ? err.message : 'An internal server error occurred.',
  });
});

// ---------------------------------------------------------------------------
// 8. Start server only when this file is run directly (not during testing)
// ---------------------------------------------------------------------------
if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

