// Simple application — hardened for security best practices
'use strict';

const express = require('express');
const helmet = require('helmet');            // Security headers
const rateLimit = require('express-rate-limit'); // Rate limiting

const app = express();

// ── 1. Security headers (X-Content-Type-Options, X-Frame-Options, etc.) ──────
app.use(helmet());

// ── 2. Parse JSON bodies with a size limit to prevent payload attacks ─────────
app.use(express.json({ limit: '10kb' }));

// ── 3. Rate limiting — max 100 requests per 15 min per IP ─────────────────────
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  standardHeaders: true,  // Return rate-limit info in `RateLimit-*` headers
  legacyHeaders: false,   // Disable `X-RateLimit-*` headers
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// ── Routes ────────────────────────────────────────────────────────────────────

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Input validation helper
function isValidId(value) {
  const id = Number(value);
  return Number.isInteger(id) && id > 0;
}

app.get('/users', (req, res, next) => {
  try {
    // Example: validate optional ?id= query parameter if provided
    const { id } = req.query;
    if (id !== undefined && !isValidId(id)) {
      return res.status(400).json({ error: 'Invalid id parameter. Must be a positive integer.' });
    }

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const result = id ? users.filter(u => u.id === Number(id)) : users;
    res.json(result);
  } catch (err) {
    next(err); // Forward unexpected errors to the global error handler
  }
});

// ── 4. 404 handler — catches all unmatched routes ─────────────────────────────
app.use((req, res) => {
  res.status(404).json({ error: 'Route not found.' });
});

// ── 5. Global error handler — never leaks stack traces to the client ──────────
// Must have exactly 4 arguments for Express to treat it as an error handler.
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Log the full error server-side for debugging
  console.error(`[${new Date().toISOString()}] Unhandled error:`, err);

  // Send a sanitized response — no stack traces or internal details
  res.status(err.status || 500).json({
    error: err.status ? err.message : 'An internal server error occurred.',
  });
});

// ── Server startup ─────────────────────────────────────────────────────────────
const PORT = process.env.PORT || 3000;

// Only start listening when this file is run directly (not during tests)
if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

