// Simple application — hardened for security best practices

'use strict';

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();

// ---------------------------------------------------------------------------
// 1. Security Headers (helmet sets X-Content-Type-Options, X-Frame-Options,
//    Strict-Transport-Security, and more in one call)
// ---------------------------------------------------------------------------
app.use(helmet());

// ---------------------------------------------------------------------------
// 2. Body parsing with a strict size limit to prevent large-payload DoS
// ---------------------------------------------------------------------------
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// ---------------------------------------------------------------------------
// 3. Global rate limiter — 100 requests per 15 minutes per IP
// ---------------------------------------------------------------------------
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  standardHeaders: true,  // Return rate-limit info in `RateLimit-*` headers
  legacyHeaders: false,   // Disable `X-RateLimit-*` headers
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

// Health check — no user-supplied input, safe as-is
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Static user data — illustrative input validation added for query params
app.get('/users', (req, res, next) => {
  try {
    // Input validation: reject unexpected query parameters
    const allowedParams = new Set(['page', 'limit']);
    const receivedParams = Object.keys(req.query);
    const invalidParams = receivedParams.filter((p) => !allowedParams.has(p));

    if (invalidParams.length > 0) {
      return res.status(400).json({
        error: 'Invalid query parameters.',
        invalid: invalidParams,
      });
    }

    // Validate and sanitize pagination params
    const page = parseInt(req.query.page, 10) || 1;
    const limit = parseInt(req.query.limit, 10) || 10;

    if (page < 1 || limit < 1 || limit > 100) {
      return res.status(400).json({
        error: '`page` must be >= 1 and `limit` must be between 1 and 100.',
      });
    }

    // In a real app this data would come from a database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    res.json({ page, limit, total: users.length, data: users });
  } catch (err) {
    next(err); // Forward unexpected errors to the global error handler
  }
});

// ---------------------------------------------------------------------------
// 4. 404 handler — catch all unmatched routes
// ---------------------------------------------------------------------------
app.use((_req, res) => {
  res.status(404).json({ error: 'Resource not found.' });
});

// ---------------------------------------------------------------------------
// 5. Global error handler — must have 4 parameters for Express to recognise it
//    Never leak stack traces or internal details to the client.
// ---------------------------------------------------------------------------
// eslint-disable-next-line no-unused-vars
app.use((err, _req, res, _next) => {
  // Log the full error server-side for debugging
  console.error('[ERROR]', err);

  // Return a generic message to the client — no stack traces
  res.status(err.status || 500).json({
    error: err.status ? err.message : 'An internal server error occurred.',
  });
});

// ---------------------------------------------------------------------------
// 6. Use environment variable for port — never hardcode
// ---------------------------------------------------------------------------
const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = { app, server };

