'use strict';

// Required packages:
// npm install express helmet express-rate-limit

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();
const PORT = process.env.PORT || 3000;

// ---------------------------------------------------------------------------
// 1. SECURITY HEADERS
//    helmet sets ~15 protective HTTP headers (CSP, HSTS, X-Frame-Options, etc.)
// ---------------------------------------------------------------------------
app.use(helmet());

// ---------------------------------------------------------------------------
// 2. REQUEST BODY PARSING WITH SIZE LIMIT
//    Prevents denial-of-service via oversized JSON payloads.
// ---------------------------------------------------------------------------
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ---------------------------------------------------------------------------
// 3. RATE LIMITING
//    Limits each IP to 100 requests per 15-minute window.
// ---------------------------------------------------------------------------
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  standardHeaders: true,  // Return rate-limit info in `RateLimit-*` headers
  legacyHeaders: false,   // Disable `X-RateLimit-*` headers
  message: { error: 'Too many requests. Please try again later.' },
});
app.use(limiter);

// ---------------------------------------------------------------------------
// 4. ROUTES
// ---------------------------------------------------------------------------

// Health check — no sensitive data, safe to be public
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users endpoint — input validation on optional query params
app.get('/users', (req, res, next) => {
  try {
    // Example: validate an optional ?id= query parameter
    const { id } = req.query;

    if (id !== undefined) {
      const parsed = Number(id);

      // Reject non-numeric, negative, non-integer, or unreasonably large IDs
      if (!Number.isInteger(parsed) || parsed <= 0 || parsed > 1_000_000) {
        return res.status(400).json({
          error: 'Invalid query parameter: "id" must be a positive integer.',
        });
      }
    }

    // NOTE: In a real application, replace this with a database query.
    // Never expose raw database errors or internal identifiers to the client.
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const result = id
      ? users.filter((u) => u.id === Number(id))
      : users;

    // Return 404 when a specific ID is requested but not found
    if (id && result.length === 0) {
      return res.status(404).json({ error: 'User not found.' });
    }

    res.json(result);
  } catch (err) {
    // Forward unexpected errors to the global error handler
    next(err);
  }
});

// ---------------------------------------------------------------------------
// 5. 404 HANDLER
//    Catches all requests to undefined routes before they reach Express defaults.
// ---------------------------------------------------------------------------
app.use((req, res) => {
  res.status(404).json({ error: 'Route not found.' });
});

// ---------------------------------------------------------------------------
// 6. GLOBAL ERROR HANDLER
//    Must have exactly 4 arguments so Express recognises it as an error handler.
//    Logs the full error server-side; sends a safe, generic message to clients.
// ---------------------------------------------------------------------------
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Log the full error internally (replace with a structured logger in production)
  console.error({
    message: err.message,
    stack: err.stack,
    url: req.originalUrl,
    method: req.method,
    timestamp: new Date().toISOString(),
  });

  // Never leak stack traces or internal details to the client
  const statusCode = err.status || err.statusCode || 500;
  res.status(statusCode).json({
    error:
      process.env.NODE_ENV === 'production'
        ? 'An unexpected error occurred.'
        : err.message, // Slightly more detail in development
  });
});

// ---------------------------------------------------------------------------
// 7. START SERVER
// ---------------------------------------------------------------------------
if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
  });
}

module.exports = app;

