'use strict';

/**
 * app.js — Express application with security best practices applied.
 *
 * Key improvements:
 *  - Security headers via helmet
 *  - Rate limiting to mitigate DoS / brute-force
 *  - Input validation with express-validator
 *  - Centralised error handling (no stack trace leakage)
 *  - Explicit 404 handler for unknown routes
 *  - Structured logging (log levels, no raw console in routes)
 *  - Port sourced from environment variable
 */

const express = require('express');
const helmet = require('helmet');                         // Security headers
const rateLimit = require('express-rate-limit');          // Rate limiting
const { param, validationResult } = require('express-validator'); // Input validation

const app = express();

// ──────────────────────────────────────────────
// 1. SECURITY HEADERS
//    Sets X-Content-Type-Options, X-Frame-Options,
//    Strict-Transport-Security, and more automatically.
// ──────────────────────────────────────────────
app.use(helmet());

// ──────────────────────────────────────────────
// 2. BODY PARSING
//    Limits payload size to mitigate large-body DoS attacks.
// ──────────────────────────────────────────────
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ──────────────────────────────────────────────
// 3. RATE LIMITING
//    Prevents brute-force and DoS attacks.
//    Tighten windowMs / max for sensitive endpoints.
// ──────────────────────────────────────────────
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                  // Max requests per window per IP
  standardHeaders: true,     // Return rate-limit info in RateLimit-* headers
  legacyHeaders: false,      // Disable X-RateLimit-* headers
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// ──────────────────────────────────────────────
// 4. STRUCTURED LOGGER (lightweight, no dependencies)
//    Replace with winston / pino in production.
// ──────────────────────────────────────────────
const logger = {
  info:  (msg, meta = {}) => console.log(JSON.stringify({ level: 'info',  msg, ...meta, ts: new Date().toISOString() })),
  warn:  (msg, meta = {}) => console.warn(JSON.stringify({ level: 'warn', msg, ...meta, ts: new Date().toISOString() })),
  error: (msg, meta = {}) => console.error(JSON.stringify({ level: 'error', msg, ...meta, ts: new Date().toISOString() })),
};

// ──────────────────────────────────────────────
// 5. STATIC DATA (replace with DB layer + sanitization)
// ──────────────────────────────────────────────
const USERS = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob',   email: 'bob@example.com'   },
];

// ──────────────────────────────────────────────
// 6. HELPER — process validation errors uniformly
// ──────────────────────────────────────────────
function handleValidationErrors(req, res, next) {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  next();
}

// ──────────────────────────────────────────────
// 7. ROUTES
// ──────────────────────────────────────────────

// GET /health — liveness probe, no sensitive data exposed
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// GET /users — return all users (no PII beyond this demo data)
app.get('/users', (req, res) => {
  res.json(USERS);
});

// GET /users/:id — validated + sanitised path parameter
app.get(
  '/users/:id',
  [
    param('id')
      .isInt({ min: 1 })         // Must be a positive integer
      .withMessage('id must be a positive integer')
      .toInt(),                  // Sanitise: cast to Number
  ],
  handleValidationErrors,
  (req, res) => {
    const user = USERS.find((u) => u.id === req.params.id);
    if (!user) {
      return res.status(404).json({ error: 'User not found.' });
    }
    res.json(user);
  },
);

// ──────────────────────────────────────────────
// 8. 404 HANDLER
//    Catches any request that didn't match a route.
//    Returns JSON (not the Express HTML default).
// ──────────────────────────────────────────────
app.use((req, res) => {
  res.status(404).json({ error: 'Resource not found.' });
});

// ──────────────────────────────────────────────
// 9. CENTRALISED ERROR HANDLER
//    Must have exactly 4 parameters so Express recognises it.
//    Never leaks stack traces to the client.
// ──────────────────────────────────────────────
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  logger.error('Unhandled error', {
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
  });

  const statusCode = typeof err.status === 'number' ? err.status : 500;

  // Never send the raw error message to the client in production
  const clientMessage =
    process.env.NODE_ENV === 'production'
      ? 'An unexpected error occurred.'
      : err.message;

  res.status(statusCode).json({ error: clientMessage });
});

// ──────────────────────────────────────────────
// 10. SERVER STARTUP
//     Port sourced from environment; fallback to 3000.
// ──────────────────────────────────────────────
const PORT = parseInt(process.env.PORT, 10) || 3000;

// Only start listening when this file is run directly,
// not when it is imported in tests.
if (require.main === module) {
  app.listen(PORT, () => {
    logger.info(`Server running`, { port: PORT, env: process.env.NODE_ENV || 'development' });
  });
}

module.exports = app;

