// Simple application with security best practices applied
// Improvements: helmet, rate limiting, input validation, error handling, logging

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');

const app = express();
const PORT = process.env.PORT || 3000;

// ---------------------------------------------------------------------------
// 1. SECURITY HEADERS
//    helmet sets ~15 HTTP headers (CSP, HSTS, X-Frame-Options, etc.) to
//    protect against common web vulnerabilities.
// ---------------------------------------------------------------------------
app.use(helmet());

// ---------------------------------------------------------------------------
// 2. CORS POLICY
//    Explicitly whitelist allowed origins instead of leaving CORS open.
//    Adjust ALLOWED_ORIGIN via environment variable per deployment.
// ---------------------------------------------------------------------------
const ALLOWED_ORIGIN = process.env.ALLOWED_ORIGIN || 'http://localhost:3000';
app.use((req, res, next) => {
  const origin = req.headers.origin;
  if (origin === ALLOWED_ORIGIN) {
    res.setHeader('Access-Control-Allow-Origin', origin);
  }
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type, Authorization');
  if (req.method === 'OPTIONS') return res.sendStatus(204);
  next();
});

// ---------------------------------------------------------------------------
// 3. RATE LIMITING
//    Limits each IP to 100 requests per 15-minute window.
//    Prevents brute-force attacks and basic DoS abuse.
// ---------------------------------------------------------------------------
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  standardHeaders: true,  // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false,   // Disable `X-RateLimit-*` headers
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// ---------------------------------------------------------------------------
// 4. REQUEST PARSING with size limits
//    Limits body size to prevent payload-based DoS attacks.
// ---------------------------------------------------------------------------
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ---------------------------------------------------------------------------
// 5. REQUEST LOGGING
//    'combined' format logs IP, method, path, status, and user-agent —
//    useful for auditing and detecting suspicious activity.
//    Use 'tiny' or a custom format in production with a log aggregator.
// ---------------------------------------------------------------------------
app.use(morgan('combined'));

// ---------------------------------------------------------------------------
// ROUTES
// ---------------------------------------------------------------------------

// Health check — intentionally minimal, exposes no internal details
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users list — query param validation example
// Supports: GET /users?limit=10&offset=0
app.get('/users', (req, res, next) => {
  try {
    // --- Input Validation ---
    const limit = parseInt(req.query.limit, 10) || 10;
    const offset = parseInt(req.query.offset, 10) || 0;

    if (isNaN(limit) || limit < 1 || limit > 100) {
      return res.status(400).json({ error: '`limit` must be an integer between 1 and 100.' });
    }
    if (isNaN(offset) || offset < 0) {
      return res.status(400).json({ error: '`offset` must be a non-negative integer.' });
    }

    // NOTE: In production, replace this static list with a database query.
    // Never expose sensitive fields (e.g. passwords, tokens) in API responses.
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const paginated = users.slice(offset, offset + limit);
    res.json({ total: users.length, limit, offset, data: paginated });
  } catch (err) {
    next(err); // Forward unexpected errors to the global error handler
  }
});

// ---------------------------------------------------------------------------
// 6. 404 HANDLER
//    Catches requests to undefined routes before they fall through silently.
// ---------------------------------------------------------------------------
app.use((req, res) => {
  res.status(404).json({ error: `Route ${req.method} ${req.path} not found.` });
});

// ---------------------------------------------------------------------------
// 7. GLOBAL ERROR HANDLER
//    Catches errors forwarded via next(err) or thrown in async middleware.
//    - Never exposes stack traces or internal details to the client.
//    - Stack traces are logged server-side for debugging.
// ---------------------------------------------------------------------------
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  console.error(`[ERROR] ${req.method} ${req.path} —`, err.stack || err.message);
  const statusCode = err.status || err.statusCode || 500;
  res.status(statusCode).json({
    error: statusCode === 500 ? 'An internal server error occurred.' : err.message,
  });
});

// ---------------------------------------------------------------------------
// SERVER STARTUP
// ---------------------------------------------------------------------------
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

