app.get('/users', (req, res) => {
  // Example: support an optional ?limit= query param, safely validated
  const rawLimit = req.query.limit;
  let limit = 50; // safe default

  if (rawLimit !== undefined) {
    const parsed = parseUserId(rawLimit); // reuse positive-int validator
    if (parsed === null || parsed > 100) {
      // [FIX #1] Reject invalid input with a clear 400, not a 500
      return res.status(400).json({ error: 'Invalid limit parameter. Must be an integer between 1 and 100.' });
