'use strict';

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();
const PORT = process.env.PORT || 3000;

// ---------------------------------------------------------------------------
// 1. SECURITY HEADERS
//    helmet sets a suite of well-known HTTP headers that mitigate common
//    web vulnerabilities (XSS, clickjacking, MIME-sniffing, etc.)
// ---------------------------------------------------------------------------
app.use(helmet());

// ---------------------------------------------------------------------------
// 2. REQUEST BODY PARSING
//    Limit payload size to prevent large-body DoS attacks.
// ---------------------------------------------------------------------------
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ---------------------------------------------------------------------------
// 3. RATE LIMITING
//    Restrict each IP to 100 requests per 15-minute window.
//    Adjust windowMs / max to suit your traffic profile.
// ---------------------------------------------------------------------------
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  standardHeaders: true,  // Return rate-limit info in RateLimit-* headers
  legacyHeaders: false,   // Disable X-RateLimit-* headers
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// ---------------------------------------------------------------------------
// 4. ROUTES
// ---------------------------------------------------------------------------

// -- Health check -----------------------------------------------------------
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// -- Users list -------------------------------------------------------------
//    Input validation: accept optional `limit` query param (1-100, default 10)
app.get('/users', (req, res, next) => {
  try {
    // Parse and validate the optional `limit` query parameter
    const rawLimit = req.query.limit;
    let limit = 10; // safe default

    if (rawLimit !== undefined) {
      const parsed = Number(rawLimit);

      if (!Number.isInteger(parsed) || parsed < 1 || parsed > 100) {
        return res.status(400).json({
          error: 'Invalid parameter: `limit` must be an integer between 1 and 100.',
        });
      }
      limit = parsed;
    }

    // In a real app this data would come from a database.
    // Only fields needed by the client should be returned (avoid over-fetching).
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    res.json(users.slice(0, limit));
  } catch (err) {
    // Forward unexpected errors to the central error handler
    next(err);
  }
});

// ---------------------------------------------------------------------------
// 5. 404 HANDLER
//    Catches requests to undefined routes before they reach the error handler.
// ---------------------------------------------------------------------------
app.use((req, res) => {
  res.status(404).json({ error: 'Resource not found.' });
});

// ---------------------------------------------------------------------------
// 6. CENTRALISED ERROR HANDLER
//    Express recognises a 4-argument middleware as an error handler.
//    • Never leak stack traces or internal details to the client in production.
//    • Log the full error server-side for debugging/auditing.
// ---------------------------------------------------------------------------
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Log full error internally (replace with a proper logger like winston/pino)
  console.error(`[${new Date().toISOString()}] Unhandled error:`, err);

  const statusCode = err.status || err.statusCode || 500;

  // Never expose stack traces or raw error messages in production
  const message =
    process.env.NODE_ENV === 'production'
      ? 'An internal server error occurred.'
      : err.message;

  res.status(statusCode).json({ error: message });
});

// ---------------------------------------------------------------------------
// 7. SERVER STARTUP
// ---------------------------------------------------------------------------
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown: stop accepting new connections on SIGTERM (e.g. in Docker/K8s)
process.on('SIGTERM', () => {
  console.log('SIGTERM received. Shutting down gracefully…');
  server.close(() => {
    console.log('Server closed.');
    process.exit(0);
  });
});

module.exports = app;

