'use strict';

const express = require('express');
const helmet = require('helmet');           // Security headers
const rateLimit = require('express-rate-limit'); // Rate limiting
const morgan = require('morgan');           // Request logging
const { query, validationResult } = require('express-validator'); // Input validation

const app = express();

// --- Security Middleware ---

// 1. Set secure HTTP headers (removes X-Powered-By, adds CSP, HSTS, etc.)
app.use(helmet());

// 2. Parse JSON bodies with a size limit to prevent payload flooding
app.use(express.json({ limit: '10kb' }));

// 3. Rate limiting — max 100 requests per 15 minutes per IP
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// 4. Request logging (use 'combined' in production for full details)
app.use(morgan(process.env.NODE_ENV === 'production' ? 'combined' : 'dev'));


// --- Routes ---

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Input validation rules for /users
const usersValidationRules = [
  query('page')
    .optional()
    .isInt({ min: 1 }).withMessage('page must be a positive integer')
    .toInt(),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 }).withMessage('limit must be between 1 and 100')
    .toInt(),
];

app.get('/users', usersValidationRules, (req, res) => {
  // Check for validation errors
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  // TODO: Replace with authenticated DB query; never expose sensitive fields without authz
  const users = [
    { id: 1, name: 'Alice' }, // Email intentionally omitted — add auth before exposing PII
    { id: 2, name: 'Bob' },
  ];

  res.json(users);
});


// --- Error Handling ---

// 404 handler for unknown routes
app.use((req, res) => {
  res.status(404).json({ error: 'Route not found' });
});

// Global error handler — MUST have 4 arguments for Express to treat it as error middleware
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Log full error internally, never expose stack traces to clients
  console.error(`[ERROR] ${req.method} ${req.url}:`, err);

  const statusCode = err.status || err.statusCode || 500;

  // In production, hide internal error details from the response
  const message =
    process.env.NODE_ENV === 'production' && statusCode === 500
      ? 'An internal server error occurred.'
      : err.message || 'An unexpected error occurred.';

  res.status(statusCode).json({ error: message });
});


// --- Server Startup ---

const PORT = parseInt(process.env.PORT, 10) || 3000;

// Only start listening when not in a test environment (allows clean test imports)
if (process.env.NODE_ENV !== 'test') {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
  });
}

module.exports = app;
